//! Actual owned cache definitions and independent fail-closed factory probes.
use gielinor_cache::{game::{Definitions,GameCache},symbols};
use gielinor_server::content::battlestaff_assembly;
use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]
fn actual_four_profiles_and_one_hundred_seven_metadata_refusals(){
 let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let seq=symbols::load(&[Path::new(&dir)],"seq",None).unwrap();let stat=symbols::load(&[Path::new(&dir)],"stat",None).unwrap();let spot=symbols::load(&[Path::new(&dir)],"spotanim",None).unwrap();
 let cache=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&cache),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let stats=cache.files(2,200,None).unwrap().unwrap();
 let ids=[("battlestaff",1391),("water_orb",571),("earth_orb",575),("fire_orb",569),("air_orb",573),("water_battlestaff",1395),("earth_battlestaff",1399),("fire_battlestaff",1393),("air_battlestaff",1397)];
 let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};
 for(_,id)in ids{defs.items.insert(id as u32,gielinor_cache::definitions::ItemType::decode(&items[&(id as u32)]).unwrap());}defs.stats.insert(12,gielinor_cache::definitions::StatType::decode(&stats[&12]).unwrap());
 let recipes=battlestaff_assembly(&objects,&seq,&spot,&stat,&defs).unwrap();assert_eq!(recipes.len(),4);for(r,(orb,out,lvl,xp,effect))in recipes.into_iter().zip([(571,1395,54,1000,1370),(575,1399,58,1125,1371),(569,1393,62,1250,1372),(573,1397,66,1375,306)]){assert_eq!((r.recipe.first,r.recipe.second,r.recipe.output,r.recipe.skill,r.recipe.level,r.recipe.base_xp,r.recipe.members),(1391,orb,out,12,lvl,0,true));assert_eq!((r.xp_tenths,r.ticks,r.animation,r.spot),(xp,2,Some(7531),Some(effect)));}
 let mut refused=0;
 for(symbol,id)in ids{for case in 0..10{let mut d=copy(&defs);let mut o=objects.clone();match case{0=>{d.items.remove(&(id as u32));},1=>d.items.get_mut(&(id as u32)).unwrap().name="Independent wrong name".into(),2=>d.items.get_mut(&(id as u32)).unwrap().members=false,3=>d.items.get_mut(&(id as u32)).unwrap().stackable=true,4=>d.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>{o.insert(symbol.into(),id+100000);},_=>{o.remove(symbol);}}assert!(battlestaff_assembly(&o,&seq,&spot,&stat,&d).is_err(),"{symbol} case{case}");refused+=1;}}
 for case in 0..9{let mut d=copy(&defs);let mut s=stat.clone();let mut q=seq.clone();match case{0=>{s.remove("crafting");},1=>{s.insert("crafting".into(),13);},2=>{d.stats.remove(&12);},3=>d.stats.get_mut(&12).unwrap().name="Wrong".into(),4=>d.stats.get_mut(&12).unwrap().unreleased=true,5=>d.stats.get_mut(&12).unwrap().min_level=0,6=>d.stats.get_mut(&12).unwrap().max_level=98,7=>{q.remove("human_battlestaff_crafting");},8=>{q.insert("human_battlestaff_crafting".into(),7532);},_=>unreachable!()}assert!(battlestaff_assembly(&objects,&q,&spot,&s,&d).is_err());refused+=1;}
 for symbol in["battlestaff_water_crafting_spotanim","battlestaff_earth_crafting_spotanim","battlestaff_fire_crafting_spotanim","battlestaff_air_crafting_spotanim"]{for alias in[false,true]{let mut p=spot.clone();if alias{p.insert(symbol.into(),9999);}else{p.remove(symbol);}assert!(battlestaff_assembly(&objects,&seq,&p,&stat,&defs).is_err());refused+=1;}}
 assert_eq!(refused,107);println!("PG_BATTLESTAFF_BINDINGS actual_items=9 stat=12 sequence=7531 spots=4 refused=107");
}
